+  if (UseCondCardMark) {
+    Label L_already_dirty;
+    __ lbu(tmp1, Address(tmp2));
+    __ beqz(tmp1, L_already_dirty);
+    __ sb(zr, Address(tmp2));
+    __ bind(L_already_dirty);
+  } else {
+    __ sb(zr, Address(tmp2));
