+  __ lbu(tmp, gc_state_fast);
+  __ beqz(tmp, *continuation());
+  __ j(*entry());
+
+  // This is were the slowpath stub will return to or the code above will
+  // jump to if the checks are false
+  __ bind(*continuation());
