+  __ lea(tmp1, addr);
+  __ shrptr(tmp1, CardTable::card_shift());
+  __ addptr(tmp1, Address(r15_thread, in_bytes(ShenandoahThreadLocalData::card_table_offset())));
+  Address card_address(tmp1, 0);
