+  if (UseCondCardMark) {
+    __ cmpb(card_address, 0);
+    __ jccb(Assembler::equal, L_done);
+  }
+  if (UseCompressedOops && CompressedOops::base() == nullptr) {
+    __ movb(card_address, r12);
+  } else {
+    __ movb(card_address, 0);
+  }
+  __ bind(L_done);
