+  for (int i = 0; i < (limbs - 1); i++) {
+    __ movq(carry, mask);
+    __ addq(carry, c[i]);
+    __ sarq(carry, bpl);
+    __ addq(c[i + 1], carry);
+    __ shlq(carry, bpl);
+    __ subq(c[i], carry);
+  }
+
+  __ pop_ppx(rdx);
+
+  for (int i = 0; i < limbs; i++) {
+    __ movq(Address(rLimbs, i * 8), c[i]);
+  }
+}
