+#ifndef SHARE_GC_SHENANDOAH_SHENANDOAHALLOCRATE_HPP
+#define SHARE_GC_SHENANDOAH_SHENANDOAHALLOCRATE_HPP
+
+#include "gc/shenandoah/shenandoahWeightedSeq.hpp"
