+void JfrRedactedEvents::emit_string_flags(bool log) {
+  if (_string_flags == nullptr) {
+    ensure_initialized();
+   _string_flags = make_array<StringFlag*>(0);
+   JVMFlag *flag = JVMFlag::flags;
