-  for (Chunk* c = _head; c != nullptr; c = c->next()) {
-    const u1* data     = c->data();
-    const u1* data_end = c->data_end();
-
-    int to_dump = data_end - data;
-    st->print_cr("# chunk %d, %d bytes", chunk_index, to_dump);
