-    return true;
-  }
-  if (!jvmti_can_hotswap_or_post_breakpoint() &&
-      JvmtiExport::can_hotswap_or_post_breakpoint()) {
-    return true;
-  }
-  if (!jvmti_can_post_on_exceptions() &&
-      JvmtiExport::can_post_on_exceptions()) {
-    return true;
-  }
-  if (!jvmti_can_pop_frame() &&
