-  SharedLibraryToHotSpotExceptionTranslation(JVMCIEnv* hotspot_env, JVMCIEnv* jni_env, jthrowable throwable) :
-    ExceptionTranslation(jni_env, hotspot_env), _throwable(throwable) {}
-};
