-void JVMCINMethodHandle::set_nmethod(nmethod* nm) {
-  BarrierSetNMethod* bs_nm = BarrierSet::barrier_set()->barrier_set_nmethod();
-  bs_nm->nmethod_entry_barrier(nm);
-  _thread->set_live_nmethod(nm);
-}
