-nmethod* JVMCIEnv::get_nmethod(JVMCIObject obj, JVMCINMethodHandle& nmethod_handle) {
-  CodeBlob* cb = get_code_blob(obj);
-  if (cb != nullptr) {
-    nmethod* nm = cb->as_nmethod_or_null();
-    if (nm != nullptr) {
-      nmethod_handle.set_nmethod(nm);
-      return nm;
-    }
-  }
-  return nullptr;
-}
