-#undef JVMCI_CHECK3
-#undef JVMCI_CHECK4
-#undef JVMCI_FLAG_CHECKED
-#endif // PRODUCT
-#undef CHECK_NOT_SET
-
-  if (JVMCILibDumpJNIConfig != nullptr) {
