+        int bufferSize = buffer.capacity();
+        if (bufferSize == 0 || (bufferSize & 0x1) != 0) {
+            throw new IllegalArgumentException("Invalid buffer size");
+        }
+        int includeMask = (includeNormal ? FLAGS_PKG_HAS_NORMAL_VERSION : 0)
