+inline const char *
+SVG::accelerator_t::doc_cache_get_svg (const svg_doc_cache_t *doc,
+                                       unsigned *len) const
+{
+  if (!doc)
+  {
+    if (len) *len = 0;
+    return nullptr;
+  }
+  if (len) *len = doc->len;
+  return doc->svg;
+}
