+static uint32_t uperm(int nbits, uint32_t k, int s, int d) {
+  s = MIN(MAX(s, 0), nbits);
+  d = MIN(MAX(d, 0), nbits);
+  uint32_t r;
+  r = (((k & 0xaaaaaaaa) >> 1) | ((k & 0x55555555) << 1));
+  r = (((r & 0xcccccccc) >> 2) | ((r & 0x33333333) << 2));
+  r = (((r & 0xf0f0f0f0) >> 4) | ((r & 0x0f0f0f0f) << 4));
+  r = (((r & 0xff00ff00) >> 8) | ((r & 0x00ff00ff) << 8));
+  r = ((r >> 16) | (r << 16)) >> (32-nbits);
