+
+  unique_lock<recursive_mutex> lock(planManager.mtx);
+
+  planManager.loadPlanFromFile();
+
+  string path = planManager.get(planKeyString());
+  if (path == "") return false;
+
+  setPath(path.c_str());
+
+  return true;
