+  size_t operator()(const Action &a) const {
+    size_t u = 0;
+    u ^= a.config;
+    u = (u << 7) | (u >> ((sizeof(u)*8)-7));
+    u ^= a.level;
+    u = (u << 7) | (u >> ((sizeof(u)*8)-7));
+    u ^= a.N;
+    return u;
+  }
+};
