+        break;
+      }
+    }
+
+    printf("%s\n", success ? "OK" : "NG");
+  }
+
+  //
+
+  if (success) {
+    cout << "OK" << endl;
+  } else {
+    cout << "NG" << endl;
+  }
+
+  return success ? 0 : -1;
