-            case "Class":
-            case "UnresolvedClass":
-            case "UnresolvedClassInError":
-                final HotSpotResolvedObjectTypeImpl type = compilerToVM().resolveTypeInPool(this, cpi);
-                if (initialize && !type.isPrimitive() && !type.isArray()) {
-                    type.ensureInitialized();
