-                switch (bits) {
-                    case Byte.SIZE:
-                        readKind = JavaKind.Byte;
-                        break;
-                    case Short.SIZE:
-                        readKind = JavaKind.Short;
-                        break;
-                    case Integer.SIZE:
-                        readKind = JavaKind.Int;
-                        break;
-                    case Long.SIZE:
