-public final class AnnotationData {
-
-    private final JavaType type;
-    private final Map<String, Object> elements;
-
-    private static final Set<Class<?>> ELEMENT_TYPES = Set.of(
-                    Boolean.class,
-                    Byte.class,
-                    Character.class,
-                    Short.class,
-                    Integer.class,
-                    Float.class,
-                    Long.class,
-                    Double.class,
-                    String.class,
-                    EnumData.class,
