-                foundEntryPointLine = l;
-                break;
-            }
-        }
-        Asserts.assertTrue(foundDisassemblyLine != -1, testCase + " : no disassembly section found");
-        Asserts.assertTrue(foundEntryPointLine != -1, testCase + " : no entry point found");
-    }
-}

