-public class GetSymbolTest {
-    private static final int CONSTANT_POOL_UTF8_TAG = 1; // see jvms, section 4.4
-
-    private static final Function<Member[], List<String>> NAMES = members ->
-            Stream.of(members)
-                    .map(Member::getName)
-                    .collect(Collectors.toList());
