-            return;
-        }
-        if (tcase.expectedException != null) {
-            throw new AssertionError("Expected exception wasn't caught: "
-                    + tcase.expectedException.getName());
-        }
-        if (tcase.isPositive) {
-            Asserts.assertNE(index, INVALID_VTABLE_INDEX,
