-            arrayKind[i] = JavaKind.Object;
-            if (template.arrayField[i] == null) {
-                arrayContent[i] = JavaConstant.NULL_POINTER;
-            } else if (template.arrayField[i] == template) {
-                arrayContent[i] = ret;
