-        for (JavaKind kind : JavaKind.values()) {
-            if (kind.isPrimitive() && kind != JavaKind.Void) {
-                kinds = arrayKinds.clone();
-                kinds[0] = kind;
-                for (int i = 1; i < kind.getByteCount() /* && i < DEFAULT_BYTE_ARRAY_LENGTH */; i++) {
-                    kinds[i] = JavaKind.Illegal;
