-              16 /* initialFrameSize */, 16 /* stackAlignment */,
-              AArch64Kind.DWORD /* narrowOopKind */,
-              /* registers */
-              AArch64.r0, AArch64.r1, AArch64.r2, AArch64.r3,
-              AArch64.r4, AArch64.r5, AArch64.r6, AArch64.r7);
