-    private void emitLoadPointer48(Register ret, long addr) {
-        // 48-bit VA
-        long a = addr;
-        emitMovz(ret, ((int)a & 0xffff), 0);
-        a >>= 16;
-        emitMovk(ret, ((int)a & 0xffff), 16);
-        a >>= 16;
-        emitMovk(ret, ((int)a & 0xffff), 32);
-        a >>= 16;
-        assert a == 0 : "invalid pointer" + Long.toHexString(addr);
-    }
