-    private void emitFatNop() {
-        // 5 byte NOP:
-        // NOP DWORD ptr [EAX + EAX*1 + 00H]
-        code.emitByte(0x0F);
-        code.emitByte(0x1F);
-        code.emitByte(0x44);
-        code.emitByte(0x00);
-        code.emitByte(0x00);
