+    enum Comparator {
+        // TODO: enable again after JDK-8385157
+        // ULT(" <  0", false),
+        // ULE(" <= 0", false),
+        // UGT(" >  0", false),
+        // UGE(" >= 0", false),
+        // UEQ(" == 0", false),
+        // UNE(" != 0", false),
+        LT(" <  ", true),
+        LE(" <= ", true),
+        GT(" >  ", true),
+        GE(" >= ", true),
+        EQ(" == ", true),
+        NE(" != ", true);
+
+        private final String token;
+        private final boolean signed;
+
+        Comparator(String token, boolean signed) {
+            this.token = token;
+            this.signed = signed;
+        }
+
+        public String getToken() {
+            return token;
+        }
+
+        public boolean isSigned() {
+            return signed;
+        }
+
+        public Comparator negate() {
+            return switch(this) {
+                // TODO: enable again after JDK-8385157
+                // case ULT -> UGE;
+                // case ULE -> UGT;
+                // case UGT -> ULE;
+                // case UGE -> ULT;
+                // case UEQ -> UNE;
+                // case UNE -> UEQ;
+                case LT -> GE;
+                case LE -> GT;
+                case GT -> LE;
+                case GE -> LT;
+                case EQ -> NE;
+                case NE -> EQ;
+            };
+        }
+
+        public Comparator flip() {
+            return switch(this) {
+                // TODO: enable again after JDK-8385157
+                // case ULT -> UGT;
+                // case ULE -> UGE;
+                // case UGT -> ULT;
+                // case UGE -> ULE;
+                // case UEQ -> UEQ;
+                // case UNE -> UNE;
+                case LT -> GT;
+                case LE -> GE;
+                case GT -> LT;
+                case GE -> LE;
+                case EQ -> EQ;
+                case NE -> NE;
+            };
+        }
+
+        static Comparator random() {
+            return values()[RANDOM.nextInt(values().length)];
+        }
+
+        static Comparator randomGreater() {
+            return RANDOM.nextBoolean() ? GE : GT;
+        }
+
+        static Comparator randomLess() {
