+                    } else if (lo == hi) {
+                        cmpIParse = "= 1"; cmpUParse = "= 0"; cmpIFinal = "= 0"; cmpUFinal = "= 0";
+                        comment = "b) impossible condition (exact) -> fold away";
+                    } else {
+                        cmpIParse = "= 2"; cmpUParse = "= 0"; cmpIFinal = "= 0"; cmpUFinal = "= 0";
+                        comment = "b) impossible condition -> fold away";
