+                    } else if (lo < hi && lo+1 == hi) {
+                        // BoolNode::Ideal: x <u 1 or x <=u 0 -> x==0 (signed)
+                        cmpIParse = "= 2"; cmpUParse = "= 0"; cmpIFinal = "= 1"; cmpUFinal = "= 0";
