+            testIRTemplate.asToken(),
+            testMethodTemplate.asToken($("test")),
+            """
+
+            @DontCompile
+            """,
+            testMethodTemplate.asToken($("reference")),
+            """
+            // --- $test end   ---
+            """
+        ));
+        return testTemplate.asToken();
+    }
