+    static long ADDReduceLongMasked(short[] a, int idx, boolean[] mask) {
+        short res = 0;
+        for (int i = idx; i < (idx + SPECIES.length()); i++) {
+            if (mask[i % SPECIES.length()]) {
+                res = scalar_add(res, a[i]);
+            }
+        }
+
+        return (long)res;
