+        Float16Vector uab0 = zab0.rearrange(unz0,zab1);
+        Float16Vector uab1 = zab0.rearrange(unz1,zab1);
+        short[] abValues1 = bothToArray(uab0, uab1);
+        assertEquals(Arrays.toString(abValues), Arrays.toString(abValues1));
